fn main() {
    let mut cmd = build_cli();
    // Clap will handle --help, --version, unknown args, etc. We need to handle subcommand dispatch ourselves after parsing.
    // Use try_get_matches to allow us to handle errors via e.exit()
    let matches = match cmd.try_get_matches_from_mut(std::env::args_os()) {
        Ok(m) => m,
        Err(e) => {
            // clap's error handling prints to stderr/stdout and exits with code 2 or 0.
            // We must ensure that when no args, it prints help to stderr and exits 2? Let's check original behavior:
            // When run with no args, original prints help to stderr and exits 2.
            // Clap's default when subcommand not required and no args given, it will succeed with no subcommand, not error.
            // So we need to handle that case manually.
            // But if e is DisplayHelp or DisplayVersion, it already handles.
            e.exit();
        }
    };

    // If no subcommand given, original behavior is to print help to stderr and exit 2 (not 0).
    // Let's mimic.
    let sub = matches.subcommand();
    if sub.is_none() {
        // Check if help or version was already handled? try_get_matches would have exited earlier for those.
        // So this is the "no subcommand" case.
        // Print help to stderr and exit 2
        let mut cmd2 = build_cli();
        let _ = cmd2.write_help(&mut io::stderr());
        std::process::exit(2);
    }

    let (name, sub_m) = sub.unwrap();
    let result: Result<()> = match name {
        "init" => handle_init(sub_m),
        "build" => handle_build(sub_m),
        "clean" => handle_clean(sub_m),
        "test" => handle_test(sub_m),
        "watch" => handle_watch(sub_m),
        "serve" => handle_serve(sub_m),
        "completions" => handle_completions(sub_m),
        _ => unreachable!(),
    };
    if let Err(e) = result {
        // For errors that should exit 101 (book errors) vs 2 (clap)
        // Check if error is anyhow with our custom exit code? We'll just exit 101 for book errors, else 2
        // But handle functions already logged error and should exit 101
        // If we get here, exit 101
        std::process::exit(101);
    }
}

fn handle_completions(m: &clap::ArgMatches) -> Result<()> {
    let shell_str = m.get_one::<String>("SHELL").unwrap();
    let shell = match shell_str.as_str() {
        "bash" => Shell::Bash,
        "elvish" => Shell::Elvish,
        "fish" => Shell::Fish,
        "powershell" => Shell::PowerShell,
        "zsh" => Shell::Zsh,
        _ => unreachable!(),
    };
    let mut cmd = build_cli();
    // Need to set bin_name to mdbook for completions? Original generates completions with "mdbook" as command name, not "executable"
    // Our build_cli uses bin_name "executable" for help, but for completions generation, we want "mdbook" as name.
    // Clap_complete uses command name, which is "mdbook" (first arg to Command::new), bin_name only affects help display? Let's check.
    // In completions generation, the command name is used. So we should generate with mdbook.
    // Let's ensure we generate with bin_name override? We'll just generate using a command with bin_name "mdbook" but also ensure help says executable.
    // For now, generate with current cmd which has bin_name executable, but clap_complete may use bin_name if set.
    // Original completions use "mdbook" as prog name: first line _mdbook() { ... } and case ",$1") cmd="mdbook"
    // So we need to ensure generation uses "mdbook".
    let mut cmd_for_gen = build_cli();
    // Override bin_name to mdbook for gen
    let mut cmd_for_gen = cmd_for_gen.bin_name("mdbook");
    generate(shell, &mut cmd_for_gen, "mdbook", &mut io::stdout());
    Ok(())
}

fn handle_init(m: &clap::ArgMatches) -> Result<()> {
    let dir_str = m.get_one::<String>("dir").map(|s| s.as_str()).unwrap_or(".");
    let dir = Path::new(dir_str);
    // Create directory if not exists
    if !dir.exists() {
        fs::create_dir_all(dir).context("failed to create dir")?;
    }
    let do_theme = m.get_flag("theme");
    let force = m.get_flag("force");
    let title_opt = m.get_one::<String>("title").cloned();
    let ignore_opt = m.get_one::<String>("ignore").cloned();

    // Handle prompts if not forced and not provided
    let mut title = title_opt;
    let mut ignore = ignore_opt;

    let need_title_prompt = title.is_none() && !force;
    let need_ignore_prompt = ignore.is_none() && !force;

    if need_ignore_prompt || need_title_prompt {
        // Need to interactively prompt
        // Original prompts:
        // "\nDo you want a .gitignore to be created? (y/n)"
        // "\nWhat title would you like to give the book? "
        // But order? From earlier: first gitignore, then title
        // Let's check: prompt output was "\nDo you want a .gitignore to be created? (y/n)\nWhat title would you like to give the book? \n\nAll done..."
        // So order is gitignore then title.

        // We need to read from stdin line by line
        // If user pipes input, we read lines; if EOF, treat as empty

        let stdin = io::stdin();
        let mut lines: Vec<String> = Vec::new();
        // Read all lines from stdin (if interactive, will block until EOF)
        // But for non-interactive case without --force and with --title/--ignore provided, we already have values.
        // So only when needed we prompt.

        // Actually original behavior when --force is not set and title/ignore not provided, it prompts.
        // It reads from stdin for each prompt.

        // We'll implement reading via locked stdin

        use std::io::BufRead;
        let mut handle = stdin.lock();
        let mut buffer = String::new();

        if need_ignore_prompt {
            print!("\nDo you want a .gitignore to be created? (y/n)\n");
            io::stdout().flush().ok();
            buffer.clear();
            let n = handle.read_line(&mut buffer).unwrap_or(0);
            let answer = buffer.trim().to_lowercase();
            if answer == "y" || answer == "yes" {
                ignore = Some("git".to_string());
            } else {
                ignore = Some("none".to_string());
            }
        }
        if need_title_prompt {
            print!("What title would you like to give the book? \n");
            io::stdout().flush().ok();
            buffer.clear();
            let n = handle.read_line(&mut buffer).unwrap_or(0);
            let t = buffer.trim().to_string();
            if !t.is_empty() {
                title = Some(t);
            } else {
                title = None;
            }
        }
    }

    // If theme flag, print copying message
    if do_theme {
        let theme_path = dir.join("theme");
        println!("\nCopying the default theme to {}", theme_path.display());
        // copy theme files from embedded assets? For now, copy from assets/theme dir that we have in repo at compile time via include
        // But at runtime, we need to have assets available. We'll embed theme files via include_bytes or copy from assets folder relative to executable? Simpler: copy from ./assets/theme if exists, else create minimal.
        copy_default_theme(&theme_path)?;
    }

    // Copy/copy? Log
    log_info("mdbook_driver::init", "Creating a new book with stub content");

    // Create book.toml
    let book_toml_path = dir.join("book.toml");
    // Only create if not exists? Original overwrites if exists (we saw it overwrites title)
    // So always write
    let mut toml_content = String::new();
    toml_content.push_str("[book]\n");
    if let Some(t) = &title {
        toml_content.push_str(&format!("title = \"{}\"\n", escape_toml(t)));
    }
    toml_content.push_str("authors = [\"mini-swe-agent\"]\n");
    toml_content.push_str("language = \"en\"\n");
    toml_content.push_str("src = \"src\"\n");
    fs::write(&book_toml_path, toml_content)?;

    // Determine src dir (from book.toml src = "src" default)
    let src_dir = dir.join("src");
    fs::create_dir_all(&src_dir)?;

    // Handle SUMMARY.md: if exists, parse and create missing files, else create default
    let summary_path = src_dir.join("SUMMARY.md");
    if summary_path.exists() {
        // Parse existing summary and create missing files
        let content = fs::read_to_string(&summary_path)?;
        let chapters = parse_summary(&content);
        for ch in chapters {
            if let Some(path) = ch.path {
                if path.is_empty() {
                    continue;
                }
                // path is like "./chapter_1.md" or "chapter_1.md"
                let rel = path.trim_start_matches("./");
                let file_path = src_dir.join(rel);
                if !file_path.exists() {
                    // create parent dirs
                    if let Some(parent) = file_path.parent() {
                        fs::create_dir_all(parent)?;
                    }
                    let title = ch.title;
                    let header = format!("# {}\n", title);
                    fs::write(&file_path, header)?;
                }
            }
        }
    } else {
        // Create default SUMMARY.md and chapter_1.md
        let summary_content = "# Summary\n\n- [Chapter 1](./chapter_1.md)\n";
        fs::write(&summary_path, summary_content)?;
        let chapter_path = src_dir.join("chapter_1.md");
        if !chapter_path.exists() {
            fs::write(&chapter_path, "# Chapter 1\n")?;
        }
    }

    // Handle .gitignore
    let ignore_val = ignore.unwrap_or_else(|| "none".to_string());
    if ignore_val == "git" {
        let gitignore_path = dir.join(".gitignore");
        fs::write(&gitignore_path, "book\n")?;
    }

    // Ensure book dir exists (empty)
    let book_dir = dir.join("book");
    fs::create_dir_all(&book_dir)?;

    println!("\nAll done, no errors...\n");
    Ok(())
}

fn escape_toml(s: &str) -> String {
    s.replace('\\', "\\\\").replace('"', "\\\"")
}

#[derive(Debug, Clone)]
struct Chapter {
    title: String,
    path: Option<String>,
    level: usize,
    is_draft: bool,
}

fn parse_summary(content: &str) -> Vec<Chapter> {
    let mut chapters = Vec::new();
    let re_link = Regex::new(r"\[([^\]]+)\]\(([^)]*)\)").unwrap();
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        if trimmed.starts_with("# ") {
            // Part title or summary title, ignore for file creation? But part title is not a file.
            continue;
        }
        if trimmed == "---" {
            continue;
        }
        // Look for link
        if let Some(caps) = re_link.captures(trimmed) {
            let title = caps.get(1).unwrap().as_str().to_string();
            let path = caps.get(2).unwrap().as_str().to_string();
            let is_draft = path.is_empty();
            // Determine if this is a chapter line (starts with - or * or just link)
            chapters.push(Chapter { title, path: Some(path), level: 0, is_draft });
        }
    }
    chapters
}

fn copy_default_theme(dest: &Path) -> Result<()> {
    // Try to copy from embedded assets/theme if exists at runtime relative to current binary? We'll embed via include_dir or just write minimal files.
    // For simplicity, create theme structure with files from assets we vendored in repo (which will be at ./assets/theme relative to workspace root, but at runtime may be different)
    // Instead, embed file contents via include_str for some minimal files, but we can also attempt to find assets dir via executable path or current dir.

    // Try to locate assets/theme relative to executable or current dir
    let candidates = vec![
        Path::new("./assets/theme").to_path_buf(),
        Path::new("assets/theme").to_path_buf(),
        Path::new("/workspace/assets/theme").to_path_buf(),
    ];
    let mut found = None;
    for cand in candidates {
        if cand.exists() {
            found = Some(cand);
            break;
        }
    }
    if let Some(src) = found {
        copy_dir_recursive(&src, dest)?;
        return Ok(());
    }
    // Fallback: create minimal theme
    fs::create_dir_all(dest)?;
    fs::create_dir_all(dest.join("css"))?;
    fs::create_dir_all(dest.join("fonts"))?;
    // Write minimal files
    fs::write(dest.join("book.js"), "// theme book.js")?;
    fs::write(dest.join("css/general.css"), "/* general */")?;
    fs::write(dest.join("css/chrome.css"), "/* chrome */")?;
    fs::write(dest.join("css/print.css"), "/* print */")?;
    fs::write(dest.join("css/variables.css"), "/* variables */")?;
    fs::write(dest.join("highlight.css"), "/* hl */")?;
    fs::write(dest.join("highlight.js"), "// hl")?;
    fs::write(dest.join("index.hbs"), "<html></html>")?;
    Ok(())
}

fn copy_dir_recursive(src: &Path, dst: &Path) -> Result<()> {
    fs::create_dir_all(dst)?;
    for entry in WalkDir::new(src) {
        let entry = entry?;
        let path = entry.path();
        let rel = path.strip_prefix(src).unwrap();
        let dest = dst.join(rel);
        if entry.file_type().is_dir() {
            fs::create_dir_all(&dest)?;
        } else {
            if let Some(parent) = dest.parent() {
                fs::create_dir_all(parent)?;
            }
            fs::copy(path, &dest)?;
        }
    }
    Ok(())
}

