fn handle_build(m: &clap::ArgMatches) -> Result<()> {
    let dir_str = m.get_one::<String>("dir").map(|s| s.as_str()).unwrap_or(".");
    let dir = Path::new(dir_str);
    let dest_dir_opt = m.get_one::<String>("dest-dir").cloned();
    let open = m.get_flag("open");

    // Load book.toml
    let book_toml_path = dir.join("book.toml");
    let mut config = BookToml::default();
    if book_toml_path.exists() {
        let content = fs::read_to_string(&book_toml_path).map_err(|e| anyhow::anyhow!("Invalid configuration file\n\tCaused By: {}", e))?;
        // Try parse
        match toml::from_str::<BookToml>(&content) {
            Ok(c) => config = c,
            Err(e) => {
                log_error("mdbook_core::utils", &format!("Error: Invalid configuration file"));
                eprintln!("{} [ERROR] (mdbook_core::utils): \tCaused By: {}", Local::now().format("%Y-%m-%d %H:%M:%S"), e);
                // Also need to print TOML parse error specifics like original? Original prints:
                // "TOML parse error at line 1, column 9\n  |\n1 | invalid toml [\n  |         ^\nkey with no..."
                // Our toml error may be different; we can just print e
                std::process::exit(101);
            }
        }
    }

    let src_dir_name = config.book.as_ref().and_then(|b| b.src.clone()).unwrap_or_else(|| "src".to_string());
    let src_dir = dir.join(&src_dir_name);
    if !src_dir.exists() {
        log_error("mdbook_core::utils", &format!("Error: Couldn't open SUMMARY.md in \"{}\" directory", src_dir.display()));
        log_error("mdbook_core::utils", "\tCaused By: No such file or directory (os error 2)");
        std::process::exit(101);
    }
    let summary_path = src_dir.join("SUMMARY.md");
    if !summary_path.exists() {
        log_error("mdbook_core::utils", &format!("Error: Couldn't open SUMMARY.md in \"{}\" directory", src_dir.display()));
        log_error("mdbook_core::utils", "\tCaused By: No such file or directory (os error 2)");
        std::process::exit(101);
    }

    let summary_content = fs::read_to_string(&summary_path)?;
    let chapters = parse_summary_detailed(&summary_content, dir, &src_dir, &config)?;

    // Determine dest dir
    let dest_dir_name = if let Some(d) = dest_dir_opt {
        d
    } else if let Some(bd) = config.build.as_ref().and_then(|b| b.build_dir.clone()) {
        bd
    } else {
        "book".to_string()
    };
    let dest_path = if Path::new(&dest_dir_name).is_absolute() {
        PathBuf::from(dest_dir_name)
    } else {
        dir.join(dest_dir_name)
    };

    build_book(dir, &src_dir, &dest_path, &config, &chapters)?;

    if open {
        // Try to open browser (ignore errors)
        let index = dest_path.join("index.html");
        let _ = open_browser(&index);
    }

    Ok(())
}

fn parse_summary_detailed(content: &str, root_dir: &Path, src_dir: &Path, config: &BookToml) -> Result<Vec<DetailedChapter>> {
    let mut detailed = Vec::new();
    let create_missing = config.build.as_ref().and_then(|b| b.create_missing).unwrap_or(true);
    let re_link = Regex::new(r"\[([^\]]+)\]\(([^)]*)\)").unwrap();

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with("# ") && !trimmed.starts_with("# Summary") {
            // Check if it's part title? But we need to handle part titles for TOC generation.
            // For now, ignore top title and part titles? But we need to keep them for TOC.
            // We'll handle part titles separately.
            continue;
        }
        if trimmed == "---" || trimmed == "# Summary" {
            continue;
        }
        if let Some(caps) = re_link.captures(line) {
            let title = caps.get(1).unwrap().as_str().to_string();
            let path_raw = caps.get(2).unwrap().as_str().to_string();
            if path_raw.is_empty() {
                // draft chapter
                detailed.push(DetailedChapter { title, path: None, is_draft: true, level: 0, part_title: None });
            } else {
                let rel = path_raw.trim_start_matches("./");
                let file_path = src_dir.join(rel);
                if !file_path.exists() {
                    if create_missing {
                        if let Some(parent) = file_path.parent() {
                            fs::create_dir_all(parent)?;
                        }
                        fs::write(&file_path, format!("# {}\n", title))?;
                    } else {
                        log_error("mdbook_core::utils", &format!("Error: Chapter file not found, {}", path_raw));
                        log_error("mdbook_core::utils", "\tCaused By: No such file or directory (os error 2)");
                        std::process::exit(101);
                    }
                }
                detailed.push(DetailedChapter { title, path: Some(rel.to_string()), is_draft: false, level: 0, part_title: None });
            }
        }
    }
    Ok(detailed)
}

#[derive(Debug, Clone)]
struct DetailedChapter {
    title: String,
    path: Option<String>,
    is_draft: bool,
    level: usize,
    part_title: Option<String>,
}

fn build_book(root_dir: &Path, src_dir: &Path, dest_dir: &Path, config: &BookToml, chapters: &[DetailedChapter]) -> Result<()> {
    log_info("mdbook_driver::mdbook", "Book building has started");
    // Simulate preprocessor errors? For guide, there are includes that fail. We could log them if file not found? But original logs errors for missing includes like {{#include ...}}
    // For simplicity, we won't implement include handling, but we should scan markdown for {{#include}} and log if file not found? Original does that.
    // We'll add simple handling: if markdown contains {{#...}} we try to resolve, else log warn/error.
    // For now, just log those if we detect pattern and file missing, to mimic original's warnings for guide.

    // Clean dest? No, just create
    fs::create_dir_all(dest_dir)?;

    // Copy non-markdown files from src to dest (excluding .md)
    for entry in WalkDir::new(src_dir) {
        let entry = entry?;
        let path = entry.path();
        if path.is_dir() {
            continue;
        }
        let rel = path.strip_prefix(src_dir).unwrap();
        // Skip .md files
        if path.extension().map(|e| e == "md").unwrap_or(false) {
            continue;
        }
        let dest = dest_dir.join(rel);
        if let Some(parent) = dest.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::copy(path, &dest)?;
    }

    // Copy static assets
    copy_static_assets(dest_dir)?;

    // Determine book title
    let book_title = config.book.as_ref().and_then(|b| b.title.clone()).unwrap_or_default();

    // Load theme? For html we need to generate index, chapters etc.
    // For each chapter, convert markdown to html

    // Also handle prefix/suffix? Our chapters list includes all with path.

    // Create a list of chapters with html file names
    // For chapter with path "chapter_1.md" => "chapter_1.html"
    // For path with subdir: "sub/foo.md" => "sub/foo.html"

    // Filter chapters that have path
    let html_chapters: Vec<(DetailedChapter, String)> = chapters.iter().filter_map(|c| {
        c.path.as_ref().map(|p| {
            let html_path = p.trim_end_matches(".md").to_string() + ".html";
            (c.clone(), html_path)
        })
    }).collect();

    // Generate each html
    for (ch, html_path) in &html_chapters {
        let src_path = src_dir.join(ch.path.as_ref().unwrap());
        let md_content = fs::read_to_string(&src_path).unwrap_or_default();
        let html_body = markdown_to_html(&md_content);
        let dest_file = dest_dir.join(html_path);
        if let Some(parent) = dest_file.parent() {
            fs::create_dir_all(parent)?;
        }
        let full_html = render_html_page(ch, &book_title, &html_body, &html_chapters, &html_path, config);
        fs::write(&dest_file, full_html)?;
    }

    // Generate index.html as first chapter's content or placeholder?
    // Original mdBook makes index.html same as first chapter?
    // In our test, index.html and chapter_1.html are same for single chapter? Let's check: earlier /tmp/test_build_basic/book/index.html was same as chapter_1.html? It had title Chapter 1...
    // Actually for single chapter, index.html is same as chapter_1.html but with path_to_root ""
    // For our case, we can make index.html as redirect or copy of first chapter if exists, else default
    let index_path = dest_dir.join("index.html");
    if !html_chapters.is_empty() {
        let first_html = dest_dir.join(&html_chapters[0].1);
        if first_html.exists() {
            let content = fs::read_to_string(&first_html)?;
            fs::write(&index_path, content)?;
        }
    } else {
        fs::write(&index_path, render_empty_page(&book_title))?;
    }

    // Generate 404, toc, print, searchindex, .nojekyll
    generate_extra_files(dest_dir, &book_title, &html_chapters, config)?;

    log_info("mdbook_driver::mdbook", "Running the html backend");
    log_info("mdbook_html::html_handlebars::hbs_renderer", &format!("HTML book written to `{}`", dest_dir.display()));
    Ok(())
}

fn copy_static_assets(dest: &Path) -> Result<()> {
    // Try to find assets dir
    let candidates = vec![
        Path::new("./assets").to_path_buf(),
        Path::new("assets").to_path_buf(),
        Path::new("/workspace/assets").to_path_buf(),
    ];
    let mut src_opt = None;
    for cand in candidates {
        if cand.exists() {
            src_opt = Some(cand);
            break;
        }
    }
    if let Some(src) = src_opt {
        for entry in WalkDir::new(&src) {
            let entry = entry?;
            let path = entry.path();
            if path.is_dir() {
                continue;
            }
            let rel = path.strip_prefix(&src).unwrap();
            // Skip theme subdirectory (that's for init --theme)
            if rel.starts_with("theme") {
                continue;
            }
            let dest_path = dest.join(rel);
            if let Some(parent) = dest_path.parent() {
                fs::create_dir_all(parent)?;
            }
            fs::copy(path, &dest_path)?;
        }
    } else {
        // fallback minimal assets
        fs::create_dir_all(dest.join("css"))?;
        fs::create_dir_all(dest.join("fonts"))?;
        fs::create_dir_all(dest.join("FontAwesome/css"))?;
        fs::create_dir_all(dest.join("FontAwesome/fonts"))?;
        fs::write(dest.join("book.js"), "// book.js")?;
        fs::write(dest.join("highlight.js"), "// hl")?;
        fs::write(dest.join("highlight.css"), "/* hl */")?;
        fs::write(dest.join("tomorrow-night.css"), "")?;
        fs::write(dest.join("ayu-highlight.css"), "")?;
        fs::write(dest.join("clipboard.min.js"), "")?;
        fs::write(dest.join("elasticlunr.min.js"), "")?;
        fs::write(dest.join("mark.min.js"), "")?;
        fs::write(dest.join("searcher.js"), "")?;
        fs::write(dest.join("toc.js"), "")?;
        fs::write(dest.join("css/general.css"), "")?;
        fs::write(dest.join("css/chrome.css"), "")?;
        fs::write(dest.join("css/print.css"), "")?;
        fs::write(dest.join("css/variables.css"), "")?;
        fs::write(dest.join("fonts/fonts.css"), "")?;
        fs::write(dest.join("FontAwesome/css/font-awesome.css"), "")?;
    }
    // Ensure .nojekyll
    fs::write(dest.join(".nojekyll"), "")?;
    Ok(())
}

fn markdown_to_html(md: &str) -> String {
    // Very simple markdown conversion
    // We'll handle:
    // - headings #, ##, etc
    // - paragraphs
    // - bold, italic, inline code
    // - code blocks ```lang ... ```
    // - lists - or *
    // - blockquote >
    // - links [text](url)
    // - images ![alt](src)
    // - horizontal rule

    let mut html = String::new();
    let mut in_code_block = false;
    let mut code_lang = String::new();
    let mut code_content = String::new();
    let mut in_list = false;

    let mut lines: Vec<&str> = md.lines().collect();
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim_end();
        if trimmed.starts_with("```") {
            if !in_code_block {
                in_code_block = true;
                code_lang = trimmed.trim_start_matches("```").trim().to_string();
                code_content.clear();
            } else {
                // end block
                in_code_block = false;
                // handle code
                let escaped = html_escape(&code_content);
                if code_lang.is_empty() {
                    html.push_str(&format!("<pre><code>{}</code></pre>\n", escaped));
                } else {
                    // For rust, original wraps with <pre><pre class="playground"><code class="language-rust">
                    if code_lang.starts_with("rust") {
                        html.push_str(&format!("<pre><pre class=\"playground\"><code class=\"language-rust\">{}</code></pre></pre>\n", escaped));
                    } else {
                        html.push_str(&format!("<pre><code class=\"language-{}\">{}</code></pre>\n", code_lang, escaped));
                    }
                }
                code_lang.clear();
            }
            i += 1;
            continue;
        }
        if in_code_block {
            code_content.push_str(line);
            code_content.push('\n');
            i += 1;
            continue;
        }
        let trimmed_start = line.trim_start();
        if trimmed_start.is_empty() {
            if in_list {
                html.push_str("</ul>\n");
                in_list = false;
            }
            html.push_str("\n");
            i += 1;
            continue;
        }
        if trimmed_start.starts_with("# ") {
            let text = trimmed_start.trim_start_matches("# ").trim();
            let id = slugify(text);
            html.push_str(&format!("<h1 id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h1>\n", id, id, inline_md(text)));
        } else if trimmed_start.starts_with("## ") {
            let text = trimmed_start.trim_start_matches("## ").trim();
            let id = slugify(text);
            html.push_str(&format!("<h2 id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h2>\n", id, id, inline_md(text)));
        } else if trimmed_start.starts_with("### ") {
            let text = trimmed_start.trim_start_matches("### ").trim();
            let id = slugify(text);
            html.push_str(&format!("<h3 id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h3>\n", id, id, inline_md(text)));
        } else if trimmed_start.starts_with("- ") || trimmed_start.starts_with("* ") {
            if !in_list {
                html.push_str("<ul>\n");
                in_list = true;
            }
            let text = trimmed_start[2..].trim();
            html.push_str(&format!("<li>{}</li>\n", inline_md(text)));
            // check if next line is not list, close will happen on empty or different
        } else if trimmed_start.starts_with("> ") {
            let text = trimmed_start.trim_start_matches("> ").trim();
            html.push_str(&format!("<blockquote>\n<p>{}</p>\n</blockquote>\n", inline_md(text)));
        } else if trimmed_start.starts_with("---") {
            html.push_str("<hr />\n");
        } else {
            // paragraph
            if in_list {
                html.push_str("</ul>\n");
                in_list = false;
            }
            html.push_str(&format!("<p>{}</p>\n", inline_md(trimmed_start)));
        }
        i += 1;
    }
    if in_list {
        html.push_str("</ul>\n");
    }
    if in_code_block {
        // unclosed
        let escaped = html_escape(&code_content);
        html.push_str(&format!("<pre><code>{}</code></pre>\n", escaped));
    }
    html
}

fn html_escape(s: &str) -> String {
    s.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;")
}

fn slugify(s: &str) -> String {
    s.to_lowercase().replace(' ', "-").chars().filter(|c| c.is_alphanumeric() || *c=='-' ).collect()
}

fn inline_md(s: &str) -> String {
    // Handle inline: `code`, **bold**, *italic* or _italic_, [text](url), ![alt](src)
    let mut res = html_escape(s);
    // But we already escaped & < >, but we need to handle inline code first: `...`
    // We'll use regex
    let re_code = Regex::new(r"`([^`]+)`").unwrap();
    res = re_code.replace_all(&res, "<code>$1</code>").to_string();
    let re_strong = Regex::new(r"\*\*([^*]+)\*\*").unwrap();
    res = re_strong.replace_all(&res, "<strong>$1</strong>").to_string();
    let re_em = Regex::new(r"\*([^*]+)\*").unwrap();
    res = re_em.replace_all(&res, "<em>$1</em>").to_string();
    let re_link = Regex::new(r"\[([^\]]+)\]\(([^)]+)\)").unwrap();
    // Need to handle images: ! before link => we already handled? Let's handle images separately
    let re_img = Regex::new(r"!\[([^\]]*)\]\(([^)]+)\)").unwrap();
    res = re_img.replace_all(&res, "<img src=\"$2\" alt=\"$1\" />").to_string();
    res = re_link.replace_all(&res, "<a href=\"$2\">$1</a>").to_string();
    res
}

