fn prev_next(all: &[(DetailedChapter, String)], cur: &str, is_prev: bool) -> String {
    let idx = all.iter().position(|(_, p)| p == cur);
    if let Some(i) = idx {
        if is_prev {
            if i > 0 {
                let (ch, path) = &all[i-1];
                return format!(r#"<a rel="prev" href="{}" class="mobile-nav-chapters previous" title="Previous chapter" aria-label="Previous chapter" aria-keyshortcuts="Left"><i class="fa fa-angle-left"></i></a>"#, path);
            }
        } else {
            if i + 1 < all.len() {
                let (ch, path) = &all[i+1];
                return format!(r#"<a rel="next prefetch" href="{}" class="mobile-nav-chapters next" title="Next chapter" aria-label="Next chapter" aria-keyshortcuts="Right"><i class="fa fa-angle-right"></i></a>"#, path);
            }
        }
    }
    String::new()
}
fn prev_next_wide(all: &[(DetailedChapter, String)], cur: &str, is_prev: bool) -> String {
    let idx = all.iter().position(|(_, p)| p == cur);
    if let Some(i) = idx {
        if is_prev {
            if i > 0 {
                let (ch, path) = &all[i-1];
                return format!(r#"<a rel="prev" href="{}" class="nav-chapters previous" title="Previous chapter" aria-label="Previous chapter" aria-keyshortcuts="Left"><i class="fa fa-angle-left"></i></a>"#, path);
            }
        } else {
            if i + 1 < all.len() {
                let (ch, path) = &all[i+1];
                return format!(r#"<a rel="next prefetch" href="{}" class="nav-chapters next" title="Next chapter" aria-label="Next chapter" aria-keyshortcuts="Right"><i class="fa fa-angle-right"></i></a>"#, path);
            }
        }
    }
    String::new()
}

fn render_empty_page(book_title: &str) -> String {
    format!(r#"<!DOCTYPE HTML><html><head><title>{}</title></head><body></body></html>"#, book_title)
}

fn generate_extra_files(dest: &Path, book_title: &str, chapters: &[(DetailedChapter, String)], config: &BookToml) -> Result<()> {
    // toc.html
    let toc_content = generate_toc(chapters, book_title);
    fs::write(dest.join("toc.html"), toc_content)?;
    fs::write(dest.join("toc.js"), generate_toc_js(chapters))?;
    // 404.html
    let not_found = render_html_page(&DetailedChapter{title:"Page not found".to_string(), path:None, is_draft:false, level:0, part_title:None}, book_title, "<h1>Page not found</h1>", chapters, "404.html", config);
    fs::write(dest.join("404.html"), not_found)?;
    // print.html
    let mut print_body = String::new();
    for (ch, _) in chapters {
        let src_path = dest.join(ch.path.as_ref().unwrap().trim_end_matches(".md").to_string() + ".html");
        // Instead of reading html, just use title? But we have body already? For simplicity, concatenate titles
        print_body.push_str(&format!("<h1>{}</h1>\n", ch.title));
    }
    // Better to actually read each chapter's markdown and convert? Let's just generate simple print
    let print_html = render_html_page(&DetailedChapter{title: book_title.to_string(), path:None, is_draft:false, level:0, part_title:None}, book_title, &print_body, chapters, "print.html", config);
    fs::write(dest.join("print.html"), print_html)?;
    // searchindex.js - generate minimal
    let mut index = String::new();
    index.push_str("window.search = Object.assign(window.search, JSON.parse('");
    // Build simple json
    let docs: Vec<String> = chapters.iter().enumerate().map(|(i, (ch, _))| format!(r#"{{"title":"{}","body":"","breadcrumbs":"{}","id":"{}"}}"#, ch.title, ch.title, i)).collect();
    let json = format!(r#"{{"doc_urls":[{}],"index":{{"documentStore":{{"docInfo":{{}},"docs":{{}},"length":0}},"fields":["title","body","breadcrumbs"],"index":{{}},"lang":"English","pipeline":["trimmer","stopWordFilter","stemmer"],"ref":"id","version":"0.9.5"}},"results_options":{{"limit_results":30,"teaser_word_count":30}},"search_options":{{"bool":"OR","expand":true,"fields":{{"body":{{"boost":1}},"breadcrumbs":{{"boost":1}},"title":{{"boost":2}}}}}}}}"#, 
        chapters.iter().map(|(_, p)| format!("\"{}\"", p)).collect::<Vec<_>>().join(",")
    );
    // Escape for js string
    let escaped = json.replace('\'', "\\'").replace('\\', "\\\\");
    index.push_str(&escaped);
    index.push_str("'));");
    fs::write(dest.join("searchindex.js"), index)?;
    fs::write(dest.join("searcher.js"), "// searcher")?;
    Ok(())
}

fn generate_toc(chapters: &[(DetailedChapter, String)], book_title: &str) -> String {
    let mut items = String::new();
    for (i, (ch, path)) in chapters.iter().enumerate() {
        items.push_str(&format!(r#"<li class="chapter-item expanded "><a href="{}" target="_parent"><strong aria-hidden="true">{}. </strong> {}</a></li>"#, path, i+1, ch.title));
    }
    format!(r#"<!DOCTYPE HTML><html><head><meta charset="UTF-8"><title>TOC</title></head><body><ol class="chapter">{}</ol></body></html>"#, items)
}
fn generate_toc_js(chapters: &[(DetailedChapter, String)]) -> String {
    // Simplified toc.js
    let entries: Vec<String> = chapters.iter().enumerate().map(|(i, (ch, path))| format!(r#"{{"path":"{}","title":"{}"}}"#, path, ch.title)).collect();
    format!("window.toc = [{}];", entries.join(","))
}

