fn handle_clean(m: &clap::ArgMatches) -> Result<()> {
    let dir_str = m.get_one::<String>("dir").map(|s| s.as_str()).unwrap_or(".");
    let dir = Path::new(dir_str);
    let dest_dir_opt = m.get_one::<String>("dest-dir").cloned();

    // Need to read book.toml to get build-dir if not overridden
    let book_toml_path = dir.join("book.toml");
    let mut build_dir = "book".to_string();
    if book_toml_path.exists() {
        if let Ok(content) = fs::read_to_string(&book_toml_path) {
            if let Ok(cfg) = toml::from_str::<BookToml>(&content) {
                if let Some(bd) = cfg.build.and_then(|b| b.build_dir) {
                    build_dir = bd;
                }
            } else {
                // Invalid toml => error
                log_error("mdbook_core::utils", "Error: Invalid configuration file");
                // Need to parse error details? We'll just exit 101
                std::process::exit(101);
            }
        }
    }
    if let Some(d) = dest_dir_opt {
        build_dir = d;
    }
    let dest_path = if Path::new(&build_dir).is_absolute() {
        PathBuf::from(build_dir)
    } else {
        dir.join(build_dir)
    };

    if !dest_path.exists() {
        println!("Removed 0 files");
        return Ok(());
    }

    // Calculate size and counts before deletion
    let mut file_count = 0usize;
    let mut dir_count = 0usize;
    let mut total_size = 0u64;

    // Use du -sb equivalent: sum of file sizes + dir metadata? But earlier we saw du includes dir size (6) etc.
    // For simplicity, use walkdir and sum file sizes plus dir sizes via metadata? But du -sb for dir is 6 for empty, which is not file size but directory entry size (maybe 4096? but apparent size is 6)
    // Actually du -sb reports apparent size, which for directory is size of directory entry (which includes names? But for empty dir, it's 6? On our system, mkdir creates dir with size 6? Let's check: empty dir du -sb 6 matches (maybe it's just the name length?)
    // For file, du -sb = file size + 15 (?) earlier we saw 0-byte file => du 15 includes dir overhead? Let's check: empty file 0 => du 15 = dir 6 + file name overhead? Hard to replicate precisely.
    // Simpler: Use du -sb via Command to get exact same as original's reported size.

    // Try to run `du -sb <path>` and parse
    let du_output = std::process::Command::new("du").arg("-sb").arg(&dest_path).output();
    if let Ok(out) = du_output {
        if out.status.success() {
            let s = String::from_utf8_lossy(&out.stdout);
            if let Some(first) = s.split_whitespace().next() {
                if let Ok(sz) = first.parse::<u64>() {
                    total_size = sz;
                }
            }
        }
    }
    // Count files and dirs
    for entry in WalkDir::new(&dest_path) {
        let entry = entry?;
        if entry.file_type().is_file() {
            file_count += 1;
        } else if entry.file_type().is_dir() {
            // Count directories excluding the root? Original counts root as 1 when empty.
            // For empty dir, they say "1 directory". For dir with file, they say "1 file" not counting dir.
            // For nested empty subdirs, they counted 2 directories for book/sub (both). So count all dirs.
            dir_count += 1;
        }
    }
    // For file case, dir_count includes root and subdirs, but they report files, not dirs.
    // For empty/dir-only case, they report directories.

    // Remove
    if dest_path.is_dir() {
        fs::remove_dir_all(&dest_path)?;
    } else {
        fs::remove_file(&dest_path)?;
    }

    if file_count > 0 {
        let hr = human_readable(total_size);
        if file_count == 1 {
            println!("Removed 1 file, {} total", hr);
        } else {
            println!("Removed {} files, {} total", file_count, hr);
        }
    } else {
        // No files
        if dir_count == 0 {
            println!("Removed 0 files");
        } else {
            let hr = human_readable(total_size);
            if dir_count == 1 {
                println!("Removed 1 directory, {} total", hr);
            } else {
                println!("Removed {} directories, {} total", dir_count, hr);
            }
        }
    }
    Ok(())
}

fn human_readable(bytes: u64) -> String {
    if bytes < 1024 {
        format!("{}B", bytes)
    } else if bytes < 1024*1024 {
        format!("{:.2}KiB", bytes as f64 / 1024.0)
    } else if bytes < 1024*1024*1024 {
        format!("{:.2}MiB", bytes as f64 / 1024.0 / 1024.0)
    } else {
        format!("{:.2}GiB", bytes as f64 / 1024.0 / 1024.0 / 1024.0)
    }
}

