    fs::create_dir_all(&src_dir)?;

    // Handle SUMMARY.md: if exists, parse and create missing files, else create default
    let summary_path = src_dir.join("SUMMARY.md");
    if summary_path.exists() {
        // Parse existing summary and create missing files
        let content = fs::read_to_string(&summary_path)?;
        let chapters = parse_summary(&content);
        for ch in chapters {
            if let Some(path) = ch.path {
                if path.is_empty() {
                    continue;
                }
                // path is like "./chapter_1.md" or "chapter_1.md"
                let rel = path.trim_start_matches("./");
                let file_path = src_dir.join(rel);
                if !file_path.exists() {
                    // create parent dirs
                    if let Some(parent) = file_path.parent() {
                        fs::create_dir_all(parent)?;
                    }
                    let title = ch.title;
                    let header = format!("# {}\n", title);
                    fs::write(&file_path, header)?;
                }
            }
        }
    } else {
        // Create default SUMMARY.md and chapter_1.md
        let summary_content = "# Summary\n\n- [Chapter 1](./chapter_1.md)\n";
        fs::write(&summary_path, summary_content)?;
        let chapter_path = src_dir.join("chapter_1.md");
        if !chapter_path.exists() {
            fs::write(&chapter_path, "# Chapter 1\n")?;
        }
    }

    // Handle .gitignore
    let ignore_val = ignore.unwrap_or_else(|| "none".to_string());
    if ignore_val == "git" {
        let gitignore_path = dir.join(".gitignore");
        fs::write(&gitignore_path, "book\n")?;
    }

    // Ensure book dir exists (empty)
    let book_dir = dir.join("book");
    fs::create_dir_all(&book_dir)?;

    println!("\nAll done, no errors...\n");
    Ok(())
}

fn escape_toml(s: &str) -> String {
    s.replace('\\', "\\\\").replace('"', "\\\"")
}

#[derive(Debug, Clone)]
struct Chapter {
    title: String,
    path: Option<String>,
    level: usize,
    is_draft: bool,
}

fn parse_summary(content: &str) -> Vec<Chapter> {
    let mut chapters = Vec::new();
    let re_link = Regex::new(r"\[([^\]]+)\]\(([^)]*)\)").unwrap();
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        if trimmed.starts_with("# ") {
            // Part title or summary title, ignore for file creation? But part title is not a file.
            continue;
        }
        if trimmed == "---" {
            continue;
        }
        // Look for link
        if let Some(caps) = re_link.captures(trimmed) {
            let title = caps.get(1).unwrap().as_str().to_string();
            let path = caps.get(2).unwrap().as_str().to_string();
            let is_draft = path.is_empty();
            // Determine if this is a chapter line (starts with - or * or just link)
            chapters.push(Chapter { title, path: Some(path), level: 0, is_draft });
        }
    }
    chapters
}

fn copy_default_theme(dest: &Path) -> Result<()> {
    // Try to copy from embedded assets/theme if exists at runtime relative to current binary? We'll embed via include_dir or just write minimal files.
    // For simplicity, create theme structure with files from assets we vendored in repo (which will be at ./assets/theme relative to workspace root, but at runtime may be different)
    // Instead, embed file contents via include_str for some minimal files, but we can also attempt to find assets dir via executable path or current dir.

    // Try to locate assets/theme relative to executable or current dir
    let candidates = vec![
        Path::new("./assets/theme").to_path_buf(),
        Path::new("assets/theme").to_path_buf(),
        Path::new("/workspace/assets/theme").to_path_buf(),
    ];
    let mut found = None;
    for cand in candidates {
        if cand.exists() {
            found = Some(cand);
            break;
        }
    }
    if let Some(src) = found {
        copy_dir_recursive(&src, dest)?;
        return Ok(());
    }
    // Fallback: create minimal theme
    fs::create_dir_all(dest)?;
    fs::create_dir_all(dest.join("css"))?;
    fs::create_dir_all(dest.join("fonts"))?;
    // Write minimal files
    fs::write(dest.join("book.js"), "// theme book.js")?;
    fs::write(dest.join("css/general.css"), "/* general */")?;
    fs::write(dest.join("css/chrome.css"), "/* chrome */")?;
    fs::write(dest.join("css/print.css"), "/* print */")?;
    fs::write(dest.join("css/variables.css"), "/* variables */")?;
    fs::write(dest.join("highlight.css"), "/* hl */")?;
    fs::write(dest.join("highlight.js"), "// hl")?;
    fs::write(dest.join("index.hbs"), "<html></html>")?;
    Ok(())
}

fn copy_dir_recursive(src: &Path, dst: &Path) -> Result<()> {
    fs::create_dir_all(dst)?;
    for entry in WalkDir::new(src) {
        let entry = entry?;
        let path = entry.path();
        let rel = path.strip_prefix(src).unwrap();
        let dest = dst.join(rel);
        if entry.file_type().is_dir() {
            fs::create_dir_all(&dest)?;
        } else {
            if let Some(parent) = dest.parent() {
                fs::create_dir_all(parent)?;
            }
            fs::copy(path, &dest)?;
        }
    }
    Ok(())
}

