fn handle_build(m: &clap::ArgMatches) -> Result<()> {
    let dir_str = m.get_one::<String>("dir").map(|s| s.as_str()).unwrap_or(".");
    let dir = Path::new(dir_str);
    let dest_dir_opt = m.get_one::<String>("dest-dir").cloned();
    let open = m.get_flag("open");

    // Load book.toml
    let book_toml_path = dir.join("book.toml");
    let mut config = BookToml::default();
    if book_toml_path.exists() {
        let content = fs::read_to_string(&book_toml_path).map_err(|e| anyhow::anyhow!("Invalid configuration file\n\tCaused By: {}", e))?;
        // Try parse
        match toml::from_str::<BookToml>(&content) {
            Ok(c) => config = c,
            Err(e) => {
                log_error("mdbook_core::utils", &format!("Error: Invalid configuration file"));
                eprintln!("{} [ERROR] (mdbook_core::utils): \tCaused By: {}", Local::now().format("%Y-%m-%d %H:%M:%S"), e);
                // Also need to print TOML parse error specifics like original? Original prints:
                // "TOML parse error at line 1, column 9\n  |\n1 | invalid toml [\n  |         ^\nkey with no..."
                // Our toml error may be different; we can just print e
                std::process::exit(101);
            }
        }
    }

    let src_dir_name = config.book.as_ref().and_then(|b| b.src.clone()).unwrap_or_else(|| "src".to_string());
    let src_dir = dir.join(&src_dir_name);
    if !src_dir.exists() {
        log_error("mdbook_core::utils", &format!("Error: Couldn't open SUMMARY.md in \"{}\" directory", src_dir.display()));
        log_error("mdbook_core::utils", "\tCaused By: No such file or directory (os error 2)");
        std::process::exit(101);
    }
    let summary_path = src_dir.join("SUMMARY.md");
    if !summary_path.exists() {
        log_error("mdbook_core::utils", &format!("Error: Couldn't open SUMMARY.md in \"{}\" directory", src_dir.display()));
        log_error("mdbook_core::utils", "\tCaused By: No such file or directory (os error 2)");
        std::process::exit(101);
    }

    let summary_content = fs::read_to_string(&summary_path)?;
    let chapters = parse_summary_detailed(&summary_content, dir, &src_dir, &config)?;

    // Determine dest dir
    let dest_dir_name = if let Some(d) = dest_dir_opt {
        d
    } else if let Some(bd) = config.build.as_ref().and_then(|b| b.build_dir.clone()) {
        bd
    } else {
        "book".to_string()
    };
    let dest_path = if Path::new(&dest_dir_name).is_absolute() {
        PathBuf::from(dest_dir_name)
    } else {
        dir.join(dest_dir_name)
    };

    build_book(dir, &src_dir, &dest_path, &config, &chapters)?;

    if open {
        // Try to open browser (ignore errors)
        let index = dest_path.join("index.html");
        let _ = open_browser(&index);
    }

    Ok(())
}

fn parse_summary_detailed(content: &str, root_dir: &Path, src_dir: &Path, config: &BookToml) -> Result<Vec<DetailedChapter>> {
    let mut detailed = Vec::new();
    let create_missing = config.build.as_ref().and_then(|b| b.create_missing).unwrap_or(true);
    let re_link = Regex::new(r"\[([^\]]+)\]\(([^)]*)\)").unwrap();

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with("# ") && !trimmed.starts_with("# Summary") {
            // Check if it's part title? But we need to handle part titles for TOC generation.
            // For now, ignore top title and part titles? But we need to keep them for TOC.
            // We'll handle part titles separately.
            continue;
        }
        if trimmed == "---" || trimmed == "# Summary" {
            continue;
        }
        if let Some(caps) = re_link.captures(line) {
            let title = caps.get(1).unwrap().as_str().to_string();
            let path_raw = caps.get(2).unwrap().as_str().to_string();
            if path_raw.is_empty() {
                // draft chapter
                detailed.push(DetailedChapter { title, path: None, is_draft: true, level: 0, part_title: None });
            } else {
                let rel = path_raw.trim_start_matches("./");
                let file_path = src_dir.join(rel);
                if !file_path.exists() {
                    if create_missing {
                        if let Some(parent) = file_path.parent() {
                            fs::create_dir_all(parent)?;
                        }
                        fs::write(&file_path, format!("# {}\n", title))?;
                    } else {
                        log_error("mdbook_core::utils", &format!("Error: Chapter file not found, {}", path_raw));
                        log_error("mdbook_core::utils", "\tCaused By: No such file or directory (os error 2)");
                        std::process::exit(101);
                    }
                }
                detailed.push(DetailedChapter { title, path: Some(rel.to_string()), is_draft: false, level: 0, part_title: None });
            }
        }
    }
    Ok(detailed)
}

#[derive(Debug, Clone)]
struct DetailedChapter {
    title: String,
    path: Option<String>,
    is_draft: bool,
    level: usize,
    part_title: Option<String>,
