fn build_book(root_dir: &Path, src_dir: &Path, dest_dir: &Path, config: &BookToml, chapters: &[DetailedChapter]) -> Result<()> {
    log_info("mdbook_driver::mdbook", "Book building has started");
    // Simulate preprocessor errors? For guide, there are includes that fail. We could log them if file not found? But original logs errors for missing includes like {{#include ...}}
    // For simplicity, we won't implement include handling, but we should scan markdown for {{#include}} and log if file not found? Original does that.
    // We'll add simple handling: if markdown contains {{#...}} we try to resolve, else log warn/error.
    // For now, just log those if we detect pattern and file missing, to mimic original's warnings for guide.

    // Clean dest? No, just create
    fs::create_dir_all(dest_dir)?;

    // Copy non-markdown files from src to dest (excluding .md)
    for entry in WalkDir::new(src_dir) {
        let entry = entry?;
        let path = entry.path();
        if path.is_dir() {
            continue;
        }
        let rel = path.strip_prefix(src_dir).unwrap();
        // Skip .md files
        if path.extension().map(|e| e == "md").unwrap_or(false) {
            continue;
        }
        let dest = dest_dir.join(rel);
        if let Some(parent) = dest.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::copy(path, &dest)?;
    }

    // Copy static assets
    copy_static_assets(dest_dir)?;

    // Determine book title
    let book_title = config.book.as_ref().and_then(|b| b.title.clone()).unwrap_or_default();

    // Load theme? For html we need to generate index, chapters etc.
    // For each chapter, convert markdown to html

    // Also handle prefix/suffix? Our chapters list includes all with path.

    // Create a list of chapters with html file names
    // For chapter with path "chapter_1.md" => "chapter_1.html"
    // For path with subdir: "sub/foo.md" => "sub/foo.html"

    // Filter chapters that have path
    let html_chapters: Vec<(DetailedChapter, String)> = chapters.iter().filter_map(|c| {
        c.path.as_ref().map(|p| {
            let html_path = p.trim_end_matches(".md").to_string() + ".html";
            (c.clone(), html_path)
        })
    }).collect();

    // Generate each html
    for (ch, html_path) in &html_chapters {
        let src_path = src_dir.join(ch.path.as_ref().unwrap());
        let md_content = fs::read_to_string(&src_path).unwrap_or_default();
        let html_body = markdown_to_html(&md_content);
        let dest_file = dest_dir.join(html_path);
        if let Some(parent) = dest_file.parent() {
            fs::create_dir_all(parent)?;
        }
        let full_html = render_html_page(ch, &book_title, &html_body, &html_chapters, &html_path, config);
        fs::write(&dest_file, full_html)?;
    }

    // Generate index.html as first chapter's content or placeholder?
    // Original mdBook makes index.html same as first chapter?
    // In our test, index.html and chapter_1.html are same for single chapter? Let's check: earlier /tmp/test_build_basic/book/index.html was same as chapter_1.html? It had title Chapter 1...
    // Actually for single chapter, index.html is same as chapter_1.html but with path_to_root ""
    // For our case, we can make index.html as redirect or copy of first chapter if exists, else default
    let index_path = dest_dir.join("index.html");
    if !html_chapters.is_empty() {
        let first_html = dest_dir.join(&html_chapters[0].1);
        if first_html.exists() {
            let content = fs::read_to_string(&first_html)?;
            fs::write(&index_path, content)?;
        }
    } else {
        fs::write(&index_path, render_empty_page(&book_title))?;
    }

    // Generate 404, toc, print, searchindex, .nojekyll
    generate_extra_files(dest_dir, &book_title, &html_chapters, config)?;

    log_info("mdbook_driver::mdbook", "Running the html backend");
    log_info("mdbook_html::html_handlebars::hbs_renderer", &format!("HTML book written to `{}`", dest_dir.display()));
    Ok(())
}

fn copy_static_assets(dest: &Path) -> Result<()> {
    // Try to find assets dir
    let candidates = vec![
        Path::new("./assets").to_path_buf(),
        Path::new("assets").to_path_buf(),
        Path::new("/workspace/assets").to_path_buf(),
    ];
    let mut src_opt = None;
    for cand in candidates {
        if cand.exists() {
            src_opt = Some(cand);
            break;
        }
