                .arg(Arg::new("open").short('o').long("open").help("Opens the compiled book in a web browser").action(ArgAction::SetTrue))
        )
        .subcommand(
            Command::new("clean")
                .about("Deletes a built book")
                .arg(Arg::new("dir").help("Root directory for the book\n(Defaults to the current directory when omitted)"))
                .arg(Arg::new("dest-dir").short('d').long("dest-dir").value_name("dest-dir").help("Output directory for the book\nRelative paths are interpreted relative to the book's root directory.\nIf omitted, mdBook uses build.build-dir from book.toml or defaults to\n`./book`."))
        )
        .subcommand(
            Command::new("test")
                .about("Tests that a book's Rust code samples compile")
                .arg(Arg::new("dir").help("Root directory for the book\n(Defaults to the current directory when omitted)"))
                .arg(Arg::new("dest-dir").short('d').long("dest-dir").value_name("dest-dir").help("Output directory for the book\nRelative paths are interpreted relative to the book's root directory.\nIf omitted, mdBook uses build.build-dir from book.toml or defaults to\n`./book`."))
                .arg(Arg::new("chapter").short('c').long("chapter").value_name("chapter"))
                .arg(Arg::new("library-path").short('L').long("library-path").value_name("dir").help("A comma-separated list of directories to add to the crate search path\nwhen building tests").action(ArgAction::Append))
        )
        .subcommand(
