                .arg(Arg::new("dest-dir").short('d').long("dest-dir").value_name("dest-dir").help("Output directory for the book\nRelative paths are interpreted relative to the book's root directory.\nIf omitted, mdBook uses build.build-dir from book.toml or defaults to\n`./book`."))
                .arg(Arg::new("open").short('o').long("open").help("Opens the compiled book in a web browser").action(ArgAction::SetTrue))
