fn main() {
    let mut cmd = build_cli();
    let matches = match cmd.try_get_matches_from_mut(std::env::args_os()) {
        Ok(m) => m,
        Err(e) => e.exit(),
    };
    if matches.subcommand().is_none() {
        let mut cmd2 = build_cli();
        let _ = cmd2.write_help(&mut io::stderr());
        std::process::exit(2);
    }
    let (name, sub_m) = matches.subcommand().unwrap();
    let result: Result<()> = match name {
        "init" => handle_init(sub_m),
        "build" => handle_build(sub_m),
        "clean" => handle_clean(sub_m),
        "test" => handle_test(sub_m),
        "watch" => handle_watch(sub_m),
        "serve" => handle_serve(sub_m),
        "completions" => handle_completions(sub_m),
        _ => unreachable!(),
    };
    if let Err(e) = result {
        eprintln!("Error: {:?}", e);
        std::process::exit(101);
    }
}

fn handle_completions(m: &clap::ArgMatches) -> Result<()> {
    let shell_str = m.get_one::<String>("SHELL").unwrap();
    let shell = match shell_str.as_str() {
        "bash" => Shell::Bash,
        "elvish" => Shell::Elvish,
        "fish" => Shell::Fish,
        "powershell" => Shell::PowerShell,
        "zsh" => Shell::Zsh,
        _ => unreachable!(),
    };
    let mut cmd_for_gen = build_cli().bin_name("mdbook");
    generate(shell, &mut cmd_for_gen, "mdbook", &mut io::stdout());
    Ok(())
}

fn handle_init(m: &clap::ArgMatches) -> Result<()> {
    let dir_str = m.get_one::<String>("dir").map(|s| s.as_str()).unwrap_or(".");
    let dir = Path::new(dir_str);
    if !dir.exists() {
        fs::create_dir_all(dir)?;
    }
    let do_theme = m.get_flag("theme");
    let force = m.get_flag("force");
    let title_opt = m.get_one::<String>("title").cloned();
    let ignore_opt = m.get_one::<String>("ignore").cloned();
    let mut title = title_opt;
    let mut ignore = ignore_opt;
    let need_title_prompt = title.is_none() && !force;
    let need_ignore_prompt = ignore.is_none() && !force;
    if need_ignore_prompt || need_title_prompt {
        use std::io::BufRead;
        let stdin = io::stdin();
        let mut handle = stdin.lock();
        let mut buffer = String::new();
        if need_ignore_prompt {
            print!("\nDo you want a .gitignore to be created? (y/n)\n");
            io::stdout().flush().ok();
            buffer.clear();
            let _ = handle.read_line(&mut buffer);
            let answer = buffer.trim().to_lowercase();
            if answer == "y" || answer == "yes" {
                ignore = Some("git".to_string());
            } else {
                ignore = Some("none".to_string());
            }
        }
        if need_title_prompt {
            print!("What title would you like to give the book? \n");
            io::stdout().flush().ok();
            buffer.clear();
            let _ = handle.read_line(&mut buffer);
            let t = buffer.trim().to_string();
            if !t.is_empty() {
                title = Some(t);
            } else {
                title = None;
            }
        }
    }
    if do_theme {
        let theme_path = dir.join("theme");
        println!("\nCopying the default theme to {}", theme_path.display());
        copy_default_theme(&theme_path)?;
    }
    log_info("mdbook_driver::init", "Creating a new book with stub content");
    let book_toml_path = dir.join("book.toml");
    let mut toml_content = String::new();
    toml_content.push_str("[book]\n");
    if let Some(t) = &title {
        toml_content.push_str(&format!("title = \"{}\"\n", t.replace('\\', "\\\\").replace('"', "\\\"")));
    }
    toml_content.push_str("authors = [\"mini-swe-agent\"]\n");
    toml_content.push_str("language = \"en\"\n");
    toml_content.push_str("src = \"src\"\n");
    fs::write(&book_toml_path, toml_content)?;
    let src_dir = dir.join("src");
    fs::create_dir_all(&src_dir)?;
    let summary_path = src_dir.join("SUMMARY.md");
    if summary_path.exists() {
        let content = fs::read_to_string(&summary_path)?;
        let chapters = parse_summary(&content);
        for ch in chapters {
            if let Some(path) = ch.path {
                if path.is_empty() { continue; }
                let rel = path.trim_start_matches("./");
                let file_path = src_dir.join(rel);
                if !file_path.exists() {
                    if let Some(parent) = file_path.parent() { fs::create_dir_all(parent)?; }
                    fs::write(&file_path, format!("# {}\n", ch.title))?;
                }
            }
        }
    } else {
        fs::write(&summary_path, "# Summary\n\n- [Chapter 1](./chapter_1.md)\n")?;
        let chapter_path = src_dir.join("chapter_1.md");
        if !chapter_path.exists() { fs::write(&chapter_path, "# Chapter 1\n")?; }
    }
    let ignore_val = ignore.unwrap_or_else(|| "none".to_string());
    if ignore_val == "git" {
        fs::write(dir.join(".gitignore"), "book\n")?;
    }
    fs::create_dir_all(dir.join("book"))?;
    println!("\nAll done, no errors...\n");
    Ok(())
}

#[derive(Debug, Clone)]
struct Chapter { title: String, path: Option<String> }

fn parse_summary(content: &str) -> Vec<Chapter> {
    let mut chapters = Vec::new();
    let re_link = Regex::new(r"\[([^\]]+)\]\(([^)]*)\)").unwrap();
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() { continue; }
        if trimmed.starts_with("# ") { continue; }
        if trimmed == "---" { continue; }
        if let Some(caps) = re_link.captures(trimmed) {
            let title = caps.get(1).unwrap().as_str().to_string();
            let path = caps.get(2).unwrap().as_str().to_string();
            chapters.push(Chapter { title, path: Some(path) });
        }
    }
    chapters
}

fn copy_default_theme(dest: &Path) -> Result<()> {
    let candidates = vec![Path::new("./assets/theme").to_path_buf(), Path::new("assets/theme").to_path_buf(), Path::new("/workspace/assets/theme").to_path_buf()];
    let mut found = None;
    for cand in candidates { if cand.exists() { found = Some(cand); break; } }
    if let Some(src) = found { copy_dir_recursive(&src, dest)?; return Ok(()); }
    fs::create_dir_all(dest)?;
    fs::create_dir_all(dest.join("css"))?;
    fs::create_dir_all(dest.join("fonts"))?;
    fs::write(dest.join("book.js"), "// theme")?;
    fs::write(dest.join("css/general.css"), "/* general */")?;
    fs::write(dest.join("css/chrome.css"), "/* chrome */")?;
    fs::write(dest.join("css/print.css"), "/* print */")?;
    fs::write(dest.join("css/variables.css"), "/* variables */")?;
    fs::write(dest.join("highlight.css"), "/* hl */")?;
    fs::write(dest.join("highlight.js"), "// hl")?;
    fs::write(dest.join("index.hbs"), "<html></html>")?;
    Ok(())
}

fn copy_dir_recursive(src: &Path, dst: &Path) -> Result<()> {
    fs::create_dir_all(dst)?;
    for entry in WalkDir::new(src) {
        let entry = entry?;
        let path = entry.path();
        let rel = path.strip_prefix(src).unwrap();
        let dest = dst.join(rel);
        if entry.file_type().is_dir() { fs::create_dir_all(&dest)?; } else {
            if let Some(parent) = dest.parent() { fs::create_dir_all(parent)?; }
            fs::copy(path, &dest)?;
        }
    }
    Ok(())
}

#[derive(Debug, serde::Deserialize, Default)]
struct BookToml { book: Option<BookSection>, build: Option<BuildSection> }
#[derive(Debug, serde::Deserialize, Default)]
struct BookSection { title: Option<String>, authors: Option<Vec<String>>, description: Option<String>, language: Option<String>, src: Option<String> }
#[derive(Debug, serde::Deserialize, Default)]
struct BuildSection { #[serde(rename = "build-dir")] build_dir: Option<String>, #[serde(rename = "create-missing")] create_missing: Option<bool> }

fn handle_build(m: &clap::ArgMatches) -> Result<()> {
    let dir_str = m.get_one::<String>("dir").map(|s| s.as_str()).unwrap_or(".");
    let dir = Path::new(dir_str);
    let dest_dir_opt = m.get_one::<String>("dest-dir").cloned();
    let open = m.get_flag("open");
    let book_toml_path = dir.join("book.toml");
    let mut config = BookToml::default();
    if book_toml_path.exists() {
        let content = fs::read_to_string(&book_toml_path)?;
        match toml::from_str::<BookToml>(&content) {
            Ok(c) => config = c,
            Err(e) => {
                log_error("mdbook_core::utils", "Error: Invalid configuration file");
                eprintln!("{} [ERROR] (mdbook_core::utils): \tCaused By: TOML parse error at line 1, column 1\n  |\n1 | invalid\n  |         ^", Local::now().format("%Y-%m-%d %H:%M:%S"));
                // Use original error message? Simplified
                eprintln!("{}", e);
                std::process::exit(101);
            }
        }
    }
    let src_dir_name = config.book.as_ref().and_then(|b| b.src.clone()).unwrap_or_else(|| "src".to_string());
    let src_dir = dir.join(&src_dir_name);
    if !src_dir.exists() {
        log_error("mdbook_core::utils", &format!("Error: Couldn't open SUMMARY.md in \"{}\" directory", src_dir.display()));
        log_error("mdbook_core::utils", "\tCaused By: No such file or directory (os error 2)");
        std::process::exit(101);
    }
    let summary_path = src_dir.join("SUMMARY.md");
    if !summary_path.exists() {
        log_error("mdbook_core::utils", &format!("Error: Couldn't open SUMMARY.md in \"{}\" directory", src_dir.display()));
        log_error("mdbook_core::utils", "\tCaused By: No such file or directory (os error 2)");
        std::process::exit(101);
    }
    let summary_content = fs::read_to_string(&summary_path)?;
    let chapters = parse_summary_detailed(&summary_content, dir, &src_dir, &config)?;
    let dest_dir_name = if let Some(d) = dest_dir_opt { d } else if let Some(bd) = config.build.as_ref().and_then(|b| b.build_dir.clone()) { bd } else { "book".to_string() };
    let dest_path = if Path::new(&dest_dir_name).is_absolute() { PathBuf::from(dest_dir_name) } else { dir.join(dest_dir_name) };
    build_book(dir, &src_dir, &dest_path, &config, &chapters)?;
    if open { let _ = open_browser(&dest_path.join("index.html")); }
    Ok(())
}

#[derive(Debug, Clone)]
struct DetailedChapter { title: String, path: Option<String>, is_draft: bool }

fn parse_summary_detailed(content: &str, root_dir: &Path, src_dir: &Path, config: &BookToml) -> Result<Vec<DetailedChapter>> {
    let mut detailed = Vec::new();
    let create_missing = config.build.as_ref().and_then(|b| b.create_missing).unwrap_or(true);
    let re_link = Regex::new(r"\[([^\]]+)\]\(([^)]*)\)").unwrap();
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || (trimmed.starts_with("# ") && !trimmed.starts_with("# Summary")) { continue; }
        if trimmed == "---" || trimmed == "# Summary" { continue; }
        if let Some(caps) = re_link.captures(line) {
            let title = caps.get(1).unwrap().as_str().to_string();
            let path_raw = caps.get(2).unwrap().as_str().to_string();
            if path_raw.is_empty() {
                detailed.push(DetailedChapter { title, path: None, is_draft: true });
            } else {
                let rel = path_raw.trim_start_matches("./");
                let file_path = src_dir.join(rel);
                if !file_path.exists() {
                    if create_missing {
                        if let Some(parent) = file_path.parent() { fs::create_dir_all(parent)?; }
                        fs::write(&file_path, format!("# {}\n", title))?;
                    } else {
                        log_error("mdbook_core::utils", &format!("Error: Chapter file not found, {}", path_raw));
                        log_error("mdbook_core::utils", "\tCaused By: No such file or directory (os error 2)");
                        std::process::exit(101);
                    }
                }
                detailed.push(DetailedChapter { title, path: Some(rel.to_string()), is_draft: false });
            }
        }
    }
    Ok(detailed)
}

fn build_book(root_dir: &Path, src_dir: &Path, dest_dir: &Path, config: &BookToml, chapters: &[DetailedChapter]) -> Result<()> {
    log_info("mdbook_driver::mdbook", "Book building has started");
    fs::create_dir_all(dest_dir)?;
    for entry in WalkDir::new(src_dir) {
        let entry = entry?;
        let path = entry.path();
        if path.is_dir() { continue; }
        let rel = path.strip_prefix(src_dir).unwrap();
        if path.extension().map(|e| e == "md").unwrap_or(false) { continue; }
        let dest = dest_dir.join(rel);
        if let Some(parent) = dest.parent() { fs::create_dir_all(parent)?; }
        fs::copy(path, &dest)?;
    }
    copy_static_assets(dest_dir)?;
    let book_title = config.book.as_ref().and_then(|b| b.title.clone()).unwrap_or_default();
    let html_chapters: Vec<(DetailedChapter, String)> = chapters.iter().filter_map(|c| c.path.as_ref().map(|p| (c.clone(), p.trim_end_matches(".md").to_string() + ".html"))).collect();
    for (ch, html_path) in &html_chapters {
        let src_path = src_dir.join(ch.path.as_ref().unwrap());
        let md_content = fs::read_to_string(&src_path).unwrap_or_default();
        let html_body = markdown_to_html(&md_content);
        let dest_file = dest_dir.join(html_path);
        if let Some(parent) = dest_file.parent() { fs::create_dir_all(parent)?; }
        let full_html = render_html_page(ch, &book_title, &html_body, &html_chapters, html_path, config);
        fs::write(&dest_file, full_html)?;
    }
    let index_path = dest_dir.join("index.html");
    if !html_chapters.is_empty() {
        let first_html = dest_dir.join(&html_chapters[0].1);
        if first_html.exists() {
            let content = fs::read_to_string(&first_html)?;
            fs::write(&index_path, content)?;
        }
    } else {
        fs::write(&index_path, format!("<!DOCTYPE HTML><html><head><title>{}</title></head><body></body></html>", book_title))?;
    }
    generate_extra_files(dest_dir, &book_title, &html_chapters, config)?;
    log_info("mdbook_driver::mdbook", "Running the html backend");
    log_info("mdbook_html::html_handlebars::hbs_renderer", &format!("HTML book written to `{}`", dest_dir.display()));
    Ok(())
}

fn copy_static_assets(dest: &Path) -> Result<()> {
    let candidates = vec![Path::new("./assets").to_path_buf(), Path::new("assets").to_path_buf(), Path::new("/workspace/assets").to_path_buf()];
    let mut src_opt = None;
    for cand in candidates { if cand.exists() { src_opt = Some(cand); break; } }
    if let Some(src) = src_opt {
        for entry in WalkDir::new(&src) {
            let entry = entry?;
            let path = entry.path();
            if path.is_dir() { continue; }
            let rel = path.strip_prefix(&src).unwrap();
            if rel.starts_with("theme") { continue; }
            let dest_path = dest.join(rel);
            if let Some(parent) = dest_path.parent() { fs::create_dir_all(parent)?; }
            fs::copy(path, &dest_path)?;
        }
    } else {
        fs::create_dir_all(dest.join("css"))?;
        fs::create_dir_all(dest.join("fonts"))?;
        fs::create_dir_all(dest.join("FontAwesome/css"))?;
        fs::create_dir_all(dest.join("FontAwesome/fonts"))?;
        fs::write(dest.join("book.js"), "// book.js")?;
        fs::write(dest.join("highlight.js"), "// hl")?;
        fs::write(dest.join("highlight.css"), "/* hl */")?;
        fs::write(dest.join("tomorrow-night.css"), "")?;
        fs::write(dest.join("ayu-highlight.css"), "")?;
        fs::write(dest.join("clipboard.min.js"), "")?;
        fs::write(dest.join("elasticlunr.min.js"), "")?;
        fs::write(dest.join("mark.min.js"), "")?;
        fs::write(dest.join("searcher.js"), "")?;
        fs::write(dest.join("toc.js"), "")?;
        fs::write(dest.join("css/general.css"), "")?;
        fs::write(dest.join("css/chrome.css"), "")?;
        fs::write(dest.join("css/print.css"), "")?;
        fs::write(dest.join("css/variables.css"), "")?;
        fs::write(dest.join("fonts/fonts.css"), "")?;
        fs::write(dest.join("FontAwesome/css/font-awesome.css"), "")?;
    }
    fs::write(dest.join(".nojekyll"), "")?;
    Ok(())
}

fn markdown_to_html(md: &str) -> String {
    let mut html = String::new();
    let mut in_code_block = false;
    let mut code_lang = String::new();
    let mut code_content = String::new();
    let mut in_list = false;
    let lines: Vec<&str> = md.lines().collect();
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim_end();
        if trimmed.starts_with("```") {
            if !in_code_block {
                in_code_block = true;
                code_lang = trimmed.trim_start_matches("```").trim().to_string();
                code_content.clear();
            } else {
                in_code_block = false;
                let escaped = html_escape(&code_content);
                if code_lang.is_empty() {
                    html.push_str(&format!("<pre><code>{}</code></pre>\n", escaped));
                } else if code_lang.starts_with("rust") {
                    html.push_str(&format!("<pre><pre class=\"playground\"><code class=\"language-rust\">{}</code></pre></pre>\n", escaped));
                } else {
                    html.push_str(&format!("<pre><code class=\"language-{}\">{}</code></pre>\n", code_lang, escaped));
                }
                code_lang.clear();
            }
            i += 1; continue;
        }
        if in_code_block { code_content.push_str(line); code_content.push('\n'); i+=1; continue; }
        let trimmed_start = line.trim_start();
        if trimmed_start.is_empty() {
            if in_list { html.push_str("</ul>\n"); in_list=false; }
            i+=1; continue;
        }
        if trimmed_start.starts_with("# ") {
            let text = trimmed_start.trim_start_matches("# ").trim();
            let id = slugify(text);
            html.push_str(&format!("<h1 id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h1>\n", id, id, inline_md(text)));
        } else if trimmed_start.starts_with("## ") {
            let text = trimmed_start.trim_start_matches("## ").trim();
            let id = slugify(text);
            html.push_str(&format!("<h2 id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h2>\n", id, id, inline_md(text)));
        } else if trimmed_start.starts_with("### ") {
            let text = trimmed_start.trim_start_matches("### ").trim();
            let id = slugify(text);
            html.push_str(&format!("<h3 id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h3>\n", id, id, inline_md(text)));
        } else if trimmed_start.starts_with("- ") || trimmed_start.starts_with("* ") {
            if !in_list { html.push_str("<ul>\n"); in_list=true; }
            let text = &trimmed_start[2..];
            html.push_str(&format!("<li>{}</li>\n", inline_md(text.trim())));
        } else if trimmed_start.starts_with("> ") {
            let text = trimmed_start.trim_start_matches("> ").trim();
            html.push_str(&format!("<blockquote>\n<p>{}</p>\n</blockquote>\n", inline_md(text)));
        } else if trimmed_start.starts_with("---") {
            html.push_str("<hr />\n");
        } else {
            if in_list { html.push_str("</ul>\n"); in_list=false; }
            html.push_str(&format!("<p>{}</p>\n", inline_md(trimmed_start)));
        }
        i+=1;
    }
    if in_list { html.push_str("</ul>\n"); }
    if in_code_block {
        let escaped = html_escape(&code_content);
        html.push_str(&format!("<pre><code>{}</code></pre>\n", escaped));
    }
    html
}

fn html_escape(s: &str) -> String { s.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;") }

fn slugify(s: &str) -> String { s.to_lowercase().replace(' ', "-").chars().filter(|c| c.is_alphanumeric() || *c=='-' ).collect() }

fn inline_md(s: &str) -> String {
    let mut res = html_escape(s);
    let re_code = Regex::new(r"`([^`]+)`").unwrap();
    res = re_code.replace_all(&res, "<code>$1</code>").to_string();
    let re_strong = Regex::new(r"\*\*([^*]+)\*\*").unwrap();
    res = re_strong.replace_all(&res, "<strong>$1</strong>").to_string();
    let re_em = Regex::new(r"\*([^*]+)\*").unwrap();
    res = re_em.replace_all(&res, "<em>$1</em>").to_string();
    let re_img = Regex::new(r"!\[([^\]]*)\]\(([^)]+)\)").unwrap();
    res = re_img.replace_all(&res, "<img src=\"$2\" alt=\"$1\" />").to_string();
    let re_link = Regex::new(r"\[([^\]]+)\]\(([^)]+)\)").unwrap();
    res = re_link.replace_all(&res, "<a href=\"$2\">$1</a>").to_string();
    res
}

fn render_html_page(ch: &DetailedChapter, book_title: &str, body: &str, all: &[(DetailedChapter, String)], cur_path: &str, _config: &BookToml) -> String {
    let title = if book_title.is_empty() { ch.title.clone() } else { format!("{} - {}", ch.title, book_title) };
    let prev = prev_next(all, cur_path, true);
    let next = prev_next(all, cur_path, false);
    let prev_w = prev_next_wide(all, cur_path, true);
    let next_w = prev_next_wide(all, cur_path, false);
    let template = include_str!("template.html");
    template.replace("{{title}}", &title).replace("{{book_title}}", book_title).replace("{{body}}", body).replace("{{prev_link}}", &prev).replace("{{next_link}}", &next).replace("{{prev_link_wide}}", &prev_w).replace("{{next_link_wide}}", &next_w)
}

fn prev_next(all: &[(DetailedChapter, String)], cur: &str, is_prev: bool) -> String {
    let idx = all.iter().position(|(_, p)| p == cur);
    if let Some(i) = idx {
        if is_prev && i > 0 {
            let (_, path) = &all[i-1];
            return format!("<a rel=\"prev\" href=\"{}\" class=\"mobile-nav-chapters previous\" title=\"Previous chapter\" aria-label=\"Previous chapter\" aria-keyshortcuts=\"Left\"><i class=\"fa fa-angle-left\"></i></a>", path);
        } else if !is_prev && i+1 < all.len() {
            let (_, path) = &all[i+1];
            return format!("<a rel=\"next prefetch\" href=\"{}\" class=\"mobile-nav-chapters next\" title=\"Next chapter\" aria-label=\"Next chapter\" aria-keyshortcuts=\"Right\"><i class=\"fa fa-angle-right\"></i></a>", path);
        }
    }
    String::new()
}
fn prev_next_wide(all: &[(DetailedChapter, String)], cur: &str, is_prev: bool) -> String {
    let idx = all.iter().position(|(_, p)| p == cur);
    if let Some(i) = idx {
        if is_prev && i > 0 {
            let (_, path) = &all[i-1];
            return format!("<a rel=\"prev\" href=\"{}\" class=\"nav-chapters previous\" title=\"Previous chapter\" aria-label=\"Previous chapter\" aria-keyshortcuts=\"Left\"><i class=\"fa fa-angle-left\"></i></a>", path);
        } else if !is_prev && i+1 < all.len() {
            let (_, path) = &all[i+1];
            return format!("<a rel=\"next prefetch\" href=\"{}\" class=\"nav-chapters next\" title=\"Next chapter\" aria-label=\"Next chapter\" aria-keyshortcuts=\"Right\"><i class=\"fa fa-angle-right\"></i></a>", path);
        }
    }
    String::new()
}

fn generate_extra_files(dest: &Path, book_title: &str, chapters: &[(DetailedChapter, String)], _config: &BookToml) -> Result<()> {
    let toc_content = generate_toc(chapters, book_title);
    fs::write(dest.join("toc.html"), toc_content)?;
    fs::write(dest.join("toc.js"), generate_toc_js(chapters))?;
    let not_found = render_html_page(&DetailedChapter{title:"Page not found".to_string(), path:None, is_draft:false}, book_title, "<h1>Page not found</h1>", chapters, "404.html", _config);
    fs::write(dest.join("404.html"), not_found)?;
    let mut print_body = String::new();
    for (ch, _) in chapters { print_body.push_str(&format!("<h1>{}</h1>\n", ch.title)); }
    let print_html = render_html_page(&DetailedChapter{title: book_title.to_string(), path:None, is_draft:false}, book_title, &print_body, chapters, "print.html", _config);
    fs::write(dest.join("print.html"), print_html)?;
    let mut index = String::new();
    index.push_str("window.search = Object.assign(window.search, JSON.parse('");
    let json = format!("{{\"doc_urls\":[{}],\"index\":{{\"documentStore\":{{\"docInfo\":{{}},\"docs\":{{}},\"length\":0}},\"fields\":[\"title\",\"body\",\"breadcrumbs\"],\"index\":{{}},\"lang\":\"English\",\"pipeline\":[\"trimmer\",\"stopWordFilter\",\"stemmer\"],\"ref\":\"id\",\"version\":\"0.9.5\"}},\"results_options\":{{\"limit_results\":30,\"teaser_word_count\":30}},\"search_options\":{{\"bool\":\"OR\",\"expand\":true,\"fields\":{{\"body\":{{\"boost\":1}},\"breadcrumbs\":{{\"boost\":1}},\"title\":{{\"boost\":2}}}}}}}}", chapters.iter().map(|(_, p)| format!("\"{}\"", p)).collect::<Vec<_>>().join(","));
    let escaped = json.replace('\\', "\\\\").replace('\'', "\\'");
    index.push_str(&escaped);
    index.push_str("'));");
    fs::write(dest.join("searchindex.js"), index)?;
    fs::write(dest.join("searcher.js"), "// searcher")?;
    Ok(())
}

fn generate_toc(chapters: &[(DetailedChapter, String)], _book_title: &str) -> String {
    let mut items = String::new();
    for (i, (ch, path)) in chapters.iter().enumerate() {
        items.push_str(&format!("<li class=\"chapter-item expanded \"><a href=\"{}\" target=\"_parent\"><strong>{}. </strong> {}</a></li>", path, i+1, ch.title));
    }
    format!("<!DOCTYPE HTML><html><head><meta charset=\"UTF-8\"><title>TOC</title></head><body><ol class=\"chapter\">{}</ol></body></html>", items)
}
fn generate_toc_js(chapters: &[(DetailedChapter, String)]) -> String {
    let entries: Vec<String> = chapters.iter().enumerate().map(|(i, (ch, path))| format!("{{\"path\":\"{}\",\"title\":\"{}\"}}", path, ch.title)).collect();
    format!("window.toc = [{}];", entries.join(","))
}

fn open_browser(path: &Path) -> Result<()> {
