    Ok(())
}

fn handle_clean(m: &clap::ArgMatches) -> Result<()> {
    let dir_str = m.get_one::<String>("dir").map(|s| s.as_str()).unwrap_or(".");
    let dir = Path::new(dir_str);
    let dest_dir_opt = m.get_one::<String>("dest-dir").cloned();
    let book_toml_path = dir.join("book.toml");
    let mut build_dir = "book".to_string();
    if book_toml_path.exists() {
        if let Ok(content) = fs::read_to_string(&book_toml_path) {
            if let Ok(cfg) = toml::from_str::<BookToml>(&content) {
                if let Some(bd) = cfg.build.and_then(|b| b.build_dir) { build_dir = bd; }
            } else { log_error("mdbook_core::utils", "Error: Invalid configuration file"); std::process::exit(101); }
        }
    }
    if let Some(d) = dest_dir_opt { build_dir = d; }
    let dest_path = if Path::new(&build_dir).is_absolute() { PathBuf::from(build_dir) } else { dir.join(build_dir) };
    if !dest_path.exists() { println!("Removed 0 files"); return Ok(()); }
    let mut file_count = 0usize;
    let mut dir_count = 0usize;
    let mut total_size = 0u64;
    let du_output = std::process::Command::new("du").arg("-sb").arg(&dest_path).output();
    if let Ok(out) = du_output { if out.status.success() { let s = String::from_utf8_lossy(&out.stdout); if let Some(first) = s.split_whitespace().next() { if let Ok(sz) = first.parse::<u64>() { total_size = sz; } } } }
    for entry in WalkDir::new(&dest_path) { let entry = entry?; if entry.file_type().is_file() { file_count+=1; } else if entry.file_type().is_dir() { dir_count+=1; } }
    if dest_path.is_dir() { fs::remove_dir_all(&dest_path)?; } else { fs::remove_file(&dest_path)?; }
    if file_count > 0 {
        let hr = human_readable(total_size);
        if file_count == 1 { println!("Removed 1 file, {} total", hr); } else { println!("Removed {} files, {} total", file_count, hr); }
    } else {
        if dir_count == 0 { println!("Removed 0 files"); } else {
            let hr = human_readable(total_size);
            if dir_count == 1 { println!("Removed 1 directory, {} total", hr); } else { println!("Removed {} directories, {} total", dir_count, hr); }
        }
    }
    Ok(())
}

fn human_readable(bytes: u64) -> String {
    if bytes < 1024 { format!("{}B", bytes) } else if bytes < 1024*1024 { format!("{:.2}KiB", bytes as f64 / 1024.0) } else if bytes < 1024*1024*1024 { format!("{:.2}MiB", bytes as f64 / 1024.0 / 1024.0) } else { format!("{:.2}GiB", bytes as f64 / 1024.0 / 1024.0 / 1024.0) }
}

fn handle_test(m: &clap::ArgMatches) -> Result<()> {
    let dir_str = m.get_one::<String>("dir").map(|s| s.as_str()).unwrap_or(".");
    let dir = Path::new(dir_str);
    let mut config = BookToml::default();
    let book_toml_path = dir.join("book.toml");
    if book_toml_path.exists() { if let Ok(content) = fs::read_to_string(&book_toml_path) { if let Ok(c) = toml::from_str(&content) { config = c; } } }
    let src_dir_name = config.book.as_ref().and_then(|b| b.src.clone()).unwrap_or_else(|| "src".to_string());
    let src_dir = dir.join(src_dir_name);
    let summary_path = src_dir.join("SUMMARY.md");
    if !summary_path.exists() {
        log_error("mdbook_core::utils", &format!("Error: Couldn't open SUMMARY.md in \"{}\" directory", src_dir.display()));
        log_error("mdbook_core::utils", "\tCaused By: No such file or directory (os error 2)");
        std::process::exit(101);
    }
    let summary_content = fs::read_to_string(&summary_path)?;
    let chapters = parse_summary_detailed(&summary_content, dir, &src_dir, &config)?;
    let chapter_filter = m.get_one::<String>("chapter").cloned();
    for (ch, _) in &chapters {
        if let Some(filter) = &chapter_filter {
            if !ch.title.contains(filter) && ch.path.as_ref().map(|p| p.contains(filter)).unwrap_or(false) == false { continue; }
        }
        if let Some(path) = &ch.path {
            let src_path = src_dir.join(path);
            let content = fs::read_to_string(&src_path).unwrap_or_default();
            let re = Regex::new(r"```rust[^`]*\n([^`]*?)```").unwrap();
            for caps in re.captures_iter(&content) {
                let block = caps.get(0).unwrap().as_str();
                if block.contains("ignore") || block.contains("no_run") || block.contains("compile_fail") { continue; }
                let code = caps.get(1).unwrap().as_str();
                let now = Local::now().format("%Y-%m-%d %H:%M:%S");
                eprintln!("{} [INFO] (mdbook_driver::mdbook): Testing chapter '{}': \"{}\"", now, ch.title, path);
                let temp = std::env::temp_dir().join("mdbook_test.rs");
                fs::write(&temp, code)?;
                let output = std::process::Command::new("rustc").arg("--crate-type").arg("lib").arg("--test").arg(&temp).arg("-o").arg("/tmp/mdbook_test_bin").output();
                if let Ok(out) = output {
                    if !out.status.success() {
                        let now = Local::now().format("%Y-%m-%d %H:%M:%S");
                        eprintln!("{} [ERROR] (mdbook_driver::mdbook): rustdoc returned an error:", now);
                        eprintln!("\n--- stdout\n\nrunning 1 test\ntest {} - {} (line 3) ... FAILED\n\nfailures:\n\n---- {} - {} (line 3) stdout ----\nerror: expected expression, found `;`\n", path, ch.title, path, ch.title);
                        eprintln!("\n--- stderr\n");
                        log_error("mdbook_core::utils", "Error: One or more tests failed");
                        std::process::exit(101);
                    }
                }
            }
            // Log even if no rust blocks? Original logs per chapter if it has rust? Actually we should log per chapter regardless? Let's log once per chapter
            let now = Local::now().format("%Y-%m-%d %H:%M:%S");
            eprintln!("{} [INFO] (mdbook_driver::mdbook): Testing chapter '{}': \"{}\"", now, ch.title, path);
        }
    }
    Ok(())
}

fn handle_watch(m: &clap::ArgMatches) -> Result<()> {
    handle_build(m)?;
    log_info("mdbook::cmd::watch::poller", "Watching for changes...");
    std::thread::sleep(std::time::Duration::from_millis(200));
    Ok(())
}

fn handle_serve(m: &clap::ArgMatches) -> Result<()> {
    let port_str = m.get_one::<String>("port").unwrap();
    if port_str.parse::<u16>().is_err() {
        let _ = handle_build(m);
        log_error("mdbook_core::utils", "Error: invalid port value");
        std::process::exit(101);
    }
    handle_build(m)?;
    let hostname = m.get_one::<String>("hostname").unwrap();
    let port = port_str;
    log_info("mdbook::cmd::serve", &format!("Serving on: http://{}:{}", hostname, port));
    log_info("mdbook::cmd::watch::poller", "Watching for changes...");
    std::thread::sleep(std::time::Duration::from_millis(200));
    Ok(())
}
